// Import of required libraries
import { test, expect, SkyrampClient, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    createCollection,
    getCollectionMembers,
    inviteCollectionMember,
    deleteCollectionMember,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionName = uniqueSuffix("Members Rejections");

    const collectionsPostResponse = await createCollection(client, headers, collectionName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe(collectionName);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection id').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    // The owner is the caller; take their id from the collection this test just created.
    const ownerUserId = getResponseValue(collectionsPostResponse, "response.ownerId");
    expect(ownerUserId, 'owner id').toBeGreaterThan(0);

    // The accepted request: the owner reads the collection's member list.
    const collectionsMembersGetResponse = await getCollectionMembers(client, headers, collectionId, 200);
    expect(collectionsMembersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsMembersGetResponse, "response").length, 'a new collection has no members').toBe(0);
    expect(getResponseValue(collectionsMembersGetResponse, "response.0"), 'no first member').toBeNull();

    // An invite carrying a role but no email is rejected.
    const collectionsMembersPostResponse = await inviteCollectionMember(client, headers, collectionId, {"role": "editor"}, 400);
    expect(collectionsMembersPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersPostResponse, "response"), 'missing email rejection').toBe("email is required.");

    // An invite for an email no user has is rejected.
    const collectionsMembersPost1Response = await inviteCollectionMember(client, headers, collectionId, {"email": "nobody@example.com"}, 404);
    expect(collectionsMembersPost1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(collectionsMembersPost1Response, "response"), 'unknown email rejection').toBe("User not found.");

    // A removal with no userId query parameter is rejected.
    const collectionsMembersDeleteResponse = await deleteCollectionMember(client, headers, collectionId, null, 400);
    expect(collectionsMembersDeleteResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersDeleteResponse, "response"), 'missing userId rejection').toBe("userId query param is required.");

    // The owner cannot remove themselves.
    const collectionsMembersDelete1Response = await deleteCollectionMember(client, headers, collectionId, ownerUserId, 400);
    expect(collectionsMembersDelete1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsMembersDelete1Response, "response"), 'self-removal rejection').toBe("Owner cannot remove themselves.");

    // A collection id that does not exist is rejected.
    const membersGetResponse = await getCollectionMembers(client, headers, 99999999, 404);
    expect(membersGetResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(membersGetResponse, "response"), 'unknown collection rejection').toBe("Collection not found.");

    // A non-numeric collection id is rejected.
    const abcMembersGetResponse = await getCollectionMembers(client, headers, "abc", 400);
    expect(abcMembersGetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcMembersGetResponse, "response"), 'non-numeric id rejection').toBe("Invalid collection ID.");

    // The collection this test created is removed again.
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collectionId);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);
});
